findings.remediation:
Raise the audit log retention on the extended auditing policy:
resource "azurerm_mssql_server_extended_auditing_policy" "audit" {
  retention_in_days = 90
}

Enforce TLS 1.2 on the server:
resource "azurerm_mssql_server" "db" {
  minimum_tls_version = "1.2"
}

Disable public network access and front the server with a private endpoint:
resource "azurerm_mssql_server" "db" {
  public_network_access_enabled = false
}

Create a private endpoint for the SQL server subresource:
resource "azurerm_private_endpoint" "sql" {
  subnet_id = azurerm_subnet.db.id
  private_service_connection {
    name                           = "sql-privatelink"
    private_connection_resource_id = azurerm_mssql_server.db.id
    subresource_names              = ["sqlServer"]
    is_manual_connection           = false
  }
}
